package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Wave79 passed all three exact API53 fixed-result syntax contracts.
func TestRunSearchPhraseAcceptanceContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladePhraseAcceptance53.cls"), "@IsTest private class GladePhraseAcceptance53 {\n private static List<SObject> records(){\n        List<sObject> records = new List<sObject>{\n            new Contact(LastName = 'Smith\\\\ Clark* &Garcia', FirstName = 'John', Title = 'Administrator', Department = 'IT'),\n            new Contact(LastName = 'Clark? J{}nes [] (Jackson!)', FirstName = 'Kent', Title = 'Business Manager', Department = 'Sales'),\n            new Contact(LastName = 'Smith | Clark?', FirstName = 'Jane', Title = 'Business Manager', Department = 'Business'),\n            new Contact(LastName = '^Clark~Richards: \"Johnson\"', FirstName = 'Abby', Title = 'Executive'),\n            new Contact(LastName = 'Roberston+Williams', Title = 'Director', Department = 'Sales'),\n            new Contact(LastName = 'Jackson-Clark', FirstName = 'Ben', Department = 'Sales'),\n            new Contact(LastName = 'Clark', FirstName = 'Kent', Title = 'Administrator', Department = 'Support')\n        };\n  return records;\n }\n private static List<SObject> normalRecords(){\n        return new List<sObject>{\n            new Contact(LastName = 'Smith', FirstName = 'John', Title = 'Administrator', Department = 'IT'),\n            new Contact(LastName = 'Clark', FirstName = 'Kent', Title = 'Business Manager', Department = 'Sales'),\n            new Contact(LastName = 'Smith', FirstName = 'Jane', Title = 'Business Manager', Department = 'Business'),\n            new Contact(LastName = 'Clark', FirstName = 'Abby', Title = 'Executive'),\n            new Contact(LastName = 'Roberston', Title = 'Director', Department = 'Sales'),\n            new Contact(LastName = 'Jackson', FirstName = 'Ben', Department = 'Sales'),\n            new Contact(LastName = 'Clark', FirstName = 'Kent', Title = 'Administrator', Department = 'Support')\n        };\n }\n private static List<SObject> fixed(String expression,List<SObject> rows){\n  List<Id> ids=new List<Id>();for(SObject row:rows)ids.add((Id)row.get('Id'));\n  Test.setFixedSearchResults(ids);\n  String sosl='FIND \\''+String.escapeSingleQuotes(expression)+'\\' IN ALL FIELDS RETURNING Contact(Id,FirstName,LastName,Title,Department)';\n  List<List<SObject>> groups=Search.query(sosl);\n  System.assertEquals(1,groups.size(),'one returning group');\n  System.assertEquals(new Set<Id>(ids),new Map<Id,SObject>(groups[0]).keySet(),'fixed result IDs independent of FIND text');\n  return groups[0];\n }\n @IsTest static void originalExecuteSpecialCharacters(){\n  List<SObject> rows=normalRecords();insert rows;\nString searchQuery = '^Smith\\\\ Clark* &Garcia : | ~Clark? J{}nes [] - (Jackson!) + \"Johnson\"';\n  List<SObject> actual=fixed(searchQuery,rows);\n  System.assertEquals(rows.size(),actual.size(),'original execute population');\n }\n @IsTest static void originalFindSpecialCharacters(){\n  List<SObject> rows=records();insert rows;\n  Set<String> names=new Set<String>();List<SObject> expected=new List<SObject>();\n  for(Integer i=0;i<rows.size()-1;i++){names.add((String)rows[i].get('LastName'));expected.add(rows[i]);}\n  List<SObject> raw=fixed('('+String.join(new List<String>(names),' OR ')+')',rows);\n  List<SObject> filtered=new List<SObject>();for(SObject row:raw)if(names.contains((String)row.get('LastName')))filtered.add(row);\n  System.assertEquals(expected.size(),filtered.size(),'original find postfilter population');\n  for(Integer i=0;i<filtered.size();i++)System.assertEquals((String)expected[i].get('LastName'),(String)filtered[i].get('LastName'),'original postfilter LastName '+i);\n }\n @IsTest static void quotedPhraseUsesFixedResults(){\n  List<SObject> rows=new List<SObject>{new Contact(LastName='Unrelated fixed record')};insert rows;\n  System.assertEquals(1,fixed('\"Johnson Smith\"',rows).size(),'quoted grammar with unrelated fixed value');\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladePhraseAcceptance53.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <apiVersion>53.0</apiVersion>\n    <status>Active</status>\n</ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladePhraseIndexed53.cls"), "public class GladePhraseIndexed53 {\n public static final String MARKER='glade-phrase-owned-20260906@example.invalid';\n public static final String A='glaphrasealpha',B='glaphrasebeta';\n public static List<Id> setup(){\n  System.assertEquals(0,[SELECT count() FROM Contact WHERE Email=:MARKER],'owned marker collision');\n  List<Contact> rows=new List<Contact>{new Contact(LastName=A+' '+B,Title='adjacent',Email=MARKER),new Contact(LastName=A+' bridge '+B,Title='separated',Email=MARKER),new Contact(LastName=B+' '+A,Title='reversed',Email=MARKER),new Contact(LastName=A,Title='single',Email=MARKER)};insert rows;\n  List<Id> ids=new List<Id>();for(Contact row:rows)ids.add(row.Id);return ids;\n }\n private static Map<String,Id> owned(List<Id> ids){\n  System.assertEquals(4,ids.size(),'owned IDs');System.assertEquals(4,new Set<Id>(ids).size(),'distinct IDs');\n  Map<String,Id> labels=new Map<String,Id>();for(Contact row:[SELECT Id,Title,Email FROM Contact WHERE Id IN :ids]){System.assertEquals(MARKER,row.Email,'owned marker');labels.put(row.Title,row.Id);}\n  System.assertEquals(new Set<String>{'adjacent','separated','reversed','single'},labels.keySet(),'owned labels');return labels;\n }\n private static Set<Id> matches(String expression){\n  String q='FIND \\''+String.escapeSingleQuotes(expression)+'\\' IN NAME FIELDS RETURNING Contact(Id WHERE Email = \\''+MARKER+'\\')';\n  List<List<SObject>> groups=Search.query(q);System.assertEquals(1,groups.size(),'returning group');return new Map<Id,SObject>(groups[0]).keySet();\n }\n public static Boolean ready(List<Id> ids){Map<String,Id> labels=owned(ids);return matches(A)==new Set<Id>(ids) && matches(B)==new Set<Id>{labels.get('adjacent'),labels.get('separated'),labels.get('reversed')};}\n public static String observe(List<Id> ids){\n  Map<String,Id> labels=owned(ids);System.assert(ready(ids),'INDEX_NOT_READY: no phrase observation credit');\n  List<Object> rows=new List<Object>();\n  for(String expression:new List<String>{'\"'+A+' '+B+'\"','\"'+B+' '+A+'\"',A+' '+B}){\n   Map<String,Object> row=new Map<String,Object>{'expression'=>expression};\n   try{Set<Id> found=matches(expression);List<String> names=new List<String>();for(String label:labels.keySet())if(found.contains(labels.get(label)))names.add(label);names.sort();System.assertEquals(found.size(),names.size(),'no foreign result IDs');row.put('matches',names);}catch(Exception error){row.put('type',error.getTypeName());row.put('message',error.getMessage());}\n   rows.add(row);\n  }\n  System.assertEquals(3,rows.size(),'complete expressions');return JSON.serialize(new Map<String,Object>{'done'=>true,'rows'=>rows});\n }\n public static void cleanup(List<Id> ids){owned(ids);delete [SELECT Id FROM Contact WHERE Id IN :ids AND Email=:MARKER];System.assertEquals(0,[SELECT count() FROM Contact WHERE Id IN :ids],'owned records removed');}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladePhraseIndexed53.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <apiVersion>53.0</apiVersion>\n    <status>Active</status>\n</ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 3 || got.Passed != 3 || got.Skipped != 0 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("phrase syntax contracts failed: %s", data)
	}
}
